// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != c.owner());
        vm.assume(amount > 0);

        vm.deal(address(c), amount);
        vm.prank(actor);
        bool ok;
        try c.sendMoney(address(uint160(uint256(keccak256(abi.encodePacked(actor))))), amount) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok);
    }
}
